UPDATE companies SET description='Rohrer Corporation, headquartered in Warwick, Rhode Island, operates nine manufacturing facilities across the United States and Mexico. In 2021, private equity firm Wellspring Capital Management acquired Rohrer, adding to a growth trajectory that included acquisitions of CardPak (2016), Transparent Container (2018), Coburn Carton (2021), and Jay Packaging (2022).

Rohrer provides retail packaging solutions encompassing design and engineering, printing and thermoforming, tooling and machinery, and technical service assistance. Its capabilities include soft-touch coating, printing on a wide range of substrates, and production tooling. The company runs nine regional facilities in Wadsworth, OH; Hayesville, OH; Addison, IL; Bensenville, IL; Buford, GA; Huntley, IL; Warwick, RI; Mesa, AZ; and Tijuana, B.C., Mexico, though total headcount and annual volume are not disclosed.

The company serves medical and pharmaceutical packaging, cosmetic packaging, and consumer-goods brands. Notable customers referenced include Newell Brands (Sharpie Spinner Pack), Mars Fishcare, and CE Tools. Rohrer''s ezCombo® and ecoCombo® programs target brand owners seeking sustainable, cost-effective packaging with rapid turnaround.

Rohrer differentiates itself through its ezCombo® program, which promises speed, quality, and value, and its ecoCombo® program, described as the packaging industry''s first post-consumer recycled materials combo offering. The company states a goal of zero product and service defects, 100% on-time delivery, and total customer satisfaction, backed by certifications including ISO 9001:2015, FSC Chain of Custody, and GMI Full Certification.', certifications=ARRAY['ISO 9001:2015','FSC Chain of Custody (FSC-C018819)','GMI Full Certification','PantoneLIVE','PMMI Member','Association of Visual Packaging Manufacturers Member']::text[], profile='{"capabilities": ["Design and engineering", "Printing and thermoforming", "Tooling and machinery", "Technical service assistance", "Soft touch coating", "Printing on various substrates", "Production tooling", "Sustainable packaging solutions (ezCombo, ecoCombo)", "Custom packaging programs"], "industries": ["Medical/Pharmaceutical Packaging", "Cosmetic Packaging", "Consumer Goods Packaging", "Retail Packaging"], "materials": ["Post-consumer recycled plastic", "Recyclable plastic", "FSC-certified materials", "Various printable substrates"], "equipment": ["X-Rite Color Management Scanners"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["ezCombo\u00ae program for industry-leading speed, quality, and value", "ecoCombo\u00ae: industry''s first post-consumer recycled materials combo program", "Commitment to zero defects and 100% on-time delivery", "Nine strategically located regional facilities", "Sustainability as a competitive advantage with FSC-certified and recycled materials"], "facts_used": ["Founded 1973 by John and David Rohrer -> /about-us", "Acquired by Wellspring Capital Management in 2021 -> /about-us", "Nine facilities listed including Wadsworth OH, Warwick RI, etc. -> /about-us", "Certifications: ISO 9001:2015, FSC Chain of Custody, GMI Full Certification -> /about-us", "Industries: Medical/Pharmaceutical Packaging, Cosmetic Packaging -> /about-us, /", "Customers: Newell Brands, Mars Fishcare, CE Tools -> /", "Capabilities: design & engineering, printing & thermoforming, tooling & machinery, technical service assistance -> /", "ezCombo and ecoCombo programs -> /about-us", "Headquarters Warwick RI per db -> db", "X-Rite Color Management Scanners -> /about-us"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Our award-winning team uses state-of-the-art manufacturing technologies to provide innovative retail packaging solutions", "founded_year": "1973", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='rohrer-corporation' AND approved AND profile IS NULL;
UPDATE companies SET description='Rowan Company Furniture operates a showroom and interior design studio in Greenville, South Carolina. Over the years the store has evolved while maintaining that original ethos.

The company curates a selection of home furnishings from established brands such as Taylor King, Lee Industries, Sarreid, Uttermost, Visual Comfort, and Woodbridge Furniture, alongside vintage and antique pieces sourced globally. In addition to retail sales, the firm provides interior design services ranging from single-room accessorizing to whole-house projects, supported by a team of designers. The showroom is open Monday through Saturday, with hours posted online.

Its inventory spans sofas, chairs, tables, beds, chandeliers, and accent pieces, with examples including the Taylor King apartment-size sofa, Lee Industries leather chairs, and Uttermost accent chairs. The business also caters to antique collectors with items such as vintage billiard balls and sideboards.

